import React, { useEffect, useState } from 'react';
import { fetchApplicant } from './api/apiClient';

const ApplicantDashboard = ({ applicantId }) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setError('');
      try {
        const res = await fetchApplicant(applicantId);
        setData(res.data);
      } catch (err) {
        setError('Failed to load applicant data.');
      } finally {
        setLoading(false);
      }
    };
    if (applicantId) load();
  }, [applicantId]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div style={{color:'red'}}>{error}</div>;
  if (!data) return null;

  return (
    <div>
      <h2>Applicant Dashboard</h2>
      <div><b>Name:</b> {data.name}</div>
      <div><b>Email:</b> {data.email}</div>
      <div><b>LinkedIn:</b> {data.linkedin_url}</div>
      <div><b>Resume:</b> {data.resume && data.resume.structured_data ? JSON.stringify(data.resume.structured_data) : 'Processing...'}</div>
      <div><b>Insights:</b> {data.insights ? JSON.stringify(data.insights) : 'Processing...'}</div>
    </div>
  );
};

export default ApplicantDashboard;
